begin
 select fuentes into v_datos from public.s911_catalogos where sha256='CARGA911:76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' and edicion='CARGA_2026-2027' for update;
 if not found then raise exception 'Falta iniciar la carga o ya se publicó. Revisa 000_iniciar.sql';end if;
 v_esperada=v_datos#>>'{metadatos,partes,fuentes_0008,sha256}';
 if v_datos#>>'{metadatos,lote}' is distinct from '76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' or v_esperada is distinct from '69feff8c1554af7c3e5a614a69b630f2c9609f3095c94c247d3cc1571d96f4de'
 or encode(sha256(convert_to(v_fragmento,'UTF8')),'hex') is distinct from v_esperada then
  raise exception 'Fragmento fuentes_0008 incorrecto; no se guardó';
 end if;
 update public.s911_catalogos set fuentes=jsonb_set(fuentes,'{fragmentos,fuentes_0008}',to_jsonb(v_fragmento),true)
 where sha256='CARGA911:76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' and edicion='CARGA_2026-2027';
end $parte911$;
select 'PARTE_008_OK' estado,
 (select count(*) from jsonb_object_keys(fuentes->'fragmentos')) partes_recibidas,
 33 partes_esperadas
from public.s911_catalogos where sha256='CARGA911:76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' and edicion='CARGA_2026-2027';

